/**
 * Modifier affecting/generating custom normals
 *
 * bpy.types.NormalEditModifier
 */
export interface NormalEditModifier extends R.Modifier {
  /**
   * How to affect (generate) normals Default: 'RADIAL'.
   * - `RADIAL`: Radial (From an ellipsoid (shape defined by the boundbox's dimensions, target is optional))
   * - `DIRECTIONAL`: Directional (Normals 'track' (point to) the target object)
   */
  get mode(): H.Ref<"RADIAL" | "DIRECTIONAL">;
  set mode(v: H.In<"RADIAL" | "DIRECTIONAL">);
  /** Offset from object's center Default: (0.0, 0.0, 0.0). */
  get offset(): H.Remote<M.Vector>;
  set offset(v: H.In<M.VectorLike>);
  /**
   * How to mix generated normals with existing ones Default: 'COPY'.
   * - `COPY`: Copy (Copy new normals (overwrite existing))
   * - `ADD`: Add (Copy sum of new and old normals)
   * - `SUB`: Subtract (Copy new normals minus old normals)
   * - `MUL`: Multiply (Copy product of old and new normals (not cross product))
   */
  get mix_mode(): H.Ref<"COPY" | "ADD" | "SUB" | "MUL">;
  set mix_mode(v: H.In<"COPY" | "ADD" | "SUB" | "MUL">);
  /** How much of generated normals to mix with existing ones Range: 0 to 1. Default: 1.0. */
  get mix_factor(): H.Ref<number>;
  set mix_factor(v: H.In<number>);
  /** Maximum angle between old and new normals Range: 0 to 3.1415927410125732. Default: 3.14159. */
  get mix_limit(): H.Ref<number>;
  set mix_limit(v: H.In<number>);
  /** Do not flip polygons when their normals are not consistent with their newly computed custom vertex normals Default: False. */
  get no_polynors_fix(): H.Ref<boolean>;
  set no_polynors_fix(v: H.In<boolean>);
  /** Vertex group name for selecting/weighting the affected areas Default: "". */
  get vertex_group(): H.Ref<string>;
  set vertex_group(v: H.In<string>);
  /** Invert vertex group influence Default: False. */
  get invert_vertex_group(): H.Ref<boolean>;
  set invert_vertex_group(v: H.In<boolean>);
  /** Target object used to affect normals */
  get target(): H.Ptr<R.Object>;
  set target(v: R.Object | null);
  /** Use same direction for all normals, from origin to target's center (Directional mode only) Default: True. */
  get use_direction_parallel(): H.Ref<boolean>;
  set use_direction_parallel(v: H.In<boolean>);
}
